<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRequireEmailVerificationAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRequireEmailVerificationAccessor trait.
 *
 * Covers null default, string/VO assignment via withRequireEmailVerification,
 * getRequireEmailVerification/requireEmailVerification accessors, and isRequireEmailVerificationChanged with/without original.
 */
class TenantConfigRequireEmailVerificationAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRequireEmailVerification creates a new instance with the RequireEmailVerification set
     * from a string value, and getRequireEmailVerification returns the primitive string.
     */
    public function testWithRequireEmailVerificationFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRequireEmailVerificationAccessorUnitTest();

        // Act
        $result = $holder->withRequireEmailVerification(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isRequireEmailVerification());
    }
    /**
     * Asserts that withrequireEmailVerification has access to the value object
     * from a string value, and getRequireEmailVerification returns the primitive string.
     */
    public function testWithRequireEmailVerificationFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRequireEmailVerificationAccessorUnitTest();

        // Act
        $result = $holder->withRequireEmailVerification(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->requireEmailVerification()->value());
    }
    public function testChangedRequireEmailVerification(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRequireEmailVerificationAccessorUnitTest()->withRequireEmailVerification(true);
        $original = $holder->withRequireEmailVerification(true);
        $same = $holder->withRequireEmailVerification(true);
        $modified = $holder->withRequireEmailVerification(false);

        // Act
        $withSame = $original->isRequireEmailVerificationChanged($same);
        $withDiferent = $original->isRequireEmailVerificationChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRequireEmailVerificationAccessorUnitTest
{
    use TenantConfigRequireEmailVerificationAccessor;
}
